//! Native OUTPUT reset keeps real DOM state and observer admission atomic.
use super::*;
fn fixture()->(Document,Forms,Page){fixture_content("<span id=old>before</span>tail")}
fn fixture_content(content:&str)->(Document,Forms,Page){let mut d=crate::html::parse(&format!("<html><body><form id=owner><output id=output>{content}</output><input id=field value=seed></form><form id=other><output id=unrelated>other default</output></form><div id=mount></div></body></html>"));d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-reset.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn handle(d:&mut Document,f:&mut Forms,p:&mut Page)->u32{let Value::Host(object)=p.runtime.execute("output;",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("actual output")};object}
#[test]
fn output_reset_actual_child_records_ranges_and_default_mode(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,tail=output.lastChild,list=output.childNodes,range=new Range(),watch=new MutationObserver(function(){});range.setStart(old.firstChild,1);range.setEnd(tail,2);watch.observe(output,{childList:true});");let object=handle(&mut d,&mut f,&mut p);p.begin_job();p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(output.value!=='beforetail'||output.defaultValue!=='beforetail'||output.childNodes!==list||list.length!==1||list[0]===old||old.parentNode!==null||tail.parentNode!==null||records.length!==1||records[0].target!==output||records[0].removedNodes.length!==2||records[0].removedNodes[0]!==old||records[0].removedNodes[1]!==tail||records[0].addedNodes[0]!==output.firstChild||range.startContainer!==output||range.endContainer!==output||!range.collapsed||range.startOffset)throw 'actual native reset';output.defaultValue='next';if(output.value!=='next')throw 'default mode after reset';");}
#[test]
fn output_reset_work_copy_storage_string_deadline_failures_preserve_override_and_tree(){for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{r#"var owner=document.implementation.createHTMLDocument('inert'),output=owner.createElement('output');output.textContent='A\ud800z';output.value='current';"#}else{r#"var output=document.getElementById('output');output.textContent='A\ud800z';output.value='current';"#});run(&mut d,&mut f,&mut p,"var old=output.firstChild,watch=new MutationObserver(function(){}),range=new Range();watch.observe(output,{childList:true});");if !inert{run(&mut d,&mut f,&mut p,"range.selectNodeContents(old);");}let object=handle(&mut d,&mut f,&mut p);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone());let ranges=format!("{:?}",p.state.ranges);let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};assert!(p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(format!("{:?}",p.state.ranges),ranges);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,r#"if(output.firstChild!==old||output.value!=='current'||output.defaultValue!=='A\ud800z'||watch.takeRecords().length)throw 'atomic reset refusal';"#);p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();run(&mut d,&mut f,&mut p,r#"if(output.value!=='A\ud800z'||output.defaultValue!==output.value||watch.takeRecords().length!==1)throw 'reset recovery';output.defaultValue='next';if(output.value!=='next')throw 'cleared default override';"#);}}}
#[test]
fn output_reset_protected_children_preserve_all_native_authority(){for content in ["<input value=seed>","<button>caption</button>","<img src=missing>","<script type=application/json>saved</script>","<style>.saved{color:red}</style>","<iframe></iframe>"]{let(mut d,mut f,mut p)=fixture_content(content);run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});");let object=handle(&mut d,&mut f,&mut p);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.caption.clone())).collect::<Vec<_>>();p.begin_job();let error=p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("cannot remove controls"),"{content}: {error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.caption.clone())).collect::<Vec<_>>(),controls);p.begin_job();run(&mut d,&mut f,&mut p,"if(output.firstChild!==old||watch.takeRecords().length)throw 'protected reset publication';var fresh=document.createElement('output');fresh.value='current';fresh.defaultValue='default';");let Value::Host(fresh)=p.runtime.execute("fresh;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("fresh output")};p.runtime.reset_native_output(fresh,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();run(&mut d,&mut f,&mut p,"if(fresh.value!=='default')throw 'fresh reset recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());}}
#[test]
fn output_reset_node_limit_preserves_override_and_empty_reset_needs_no_slot(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output');output.value='current';var old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});");let object=handle(&mut d,&mut f,&mut p);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len());let limit=p.state.node_limit;p.state.node_limit=d.nodes.len();p.begin_job();assert!(p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("node limit"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length)throw 'node refusal record';output.defaultValue='';");p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();assert_eq!(p.state.output_defaults.len(),0);run(&mut d,&mut f,&mut p,"if(output.value!==''||output.defaultValue!==''||output.childNodes.length||old.parentNode!==null||watch.takeRecords().length!==1)throw 'empty reset needs no slot';");p.state.node_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"output.defaultValue='next';if(output.value!=='next')throw 'empty reset cleared override';");}
#[test]
fn output_reset_inert_clone_adoption_and_author_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('output');output.textContent='A\ud800z';output.value='current';var copy=output.cloneNode(true),target=document.implementation.createHTMLDocument('target');target.adoptNode(output);Object.defineProperty(output,'defaultValue',{get:function(){throw 'author default';},configurable:true});Object.defineProperty(output,'textContent',{set:function(){throw 'author text';},configurable:true});"#);let object=handle(&mut d,&mut f,&mut p);p.begin_job();p.runtime.reset_native_output(object,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();run(&mut d,&mut f,&mut p,r#"delete output.defaultValue;delete output.textContent;if(output.value!=='A\ud800z'||output.ownerDocument!==target||output.firstChild.ownerDocument!==target||copy.value!=='current'||copy.defaultValue!=='current')throw 'native reset authority';output.textContent='later';if(output.defaultValue!=='later')throw 'adopted reset cleared override';"#);}
#[test]
fn output_reset_form_collection_storage_failure_keeps_widgets_and_outputs(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output');output.value='current';document.getElementById('field').value='edited';");p.state.rebuild(&d).unwrap();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len());let controls=f.controls.iter().map(|(n,c)|(*n,c.value.text())).collect::<Vec<_>>();let limit=p.state.retained_limit;p.state.retained_limit=p.state.retained;p.begin_job();assert!(reset_form(&mut d,&mut f,Some(&mut p),owner).unwrap_err().contains("allowance"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text())).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),owner).unwrap();run(&mut d,&mut f,&mut p,"if(output.value!=='beforetail'||document.getElementById('field').value!=='seed')throw 'whole form fresh recovery';");}

#[test]
fn output_reset_exact_current_owner_ignores_detached_other_and_scalar_aliases(){let mut d=crate::html::parse("<html><body><form id='A�z'><output id=output>beforetail</output><input id=field value=seed></form><output id=exact form='A�z'>exact default</output><output id=alias form='A�z'>alias default</output><form id=other><output id=unrelated>other default</output></form><div id=mount></div></body></html>");d.scripting_enabled=true;let owner=(0..d.nodes.len()).find(|&n|tag(&d,n)=="form").unwrap();for n in 0..d.nodes.len(){let raw=if n==owner{Some(("id",0xd800))}else{match d.attr(n,"id"){Some("exact")=>Some(("form",0xd800)),Some("alias")=>Some(("form",0xdfff)),_=>None}};if let Some((name,unit))=raw{let NodeKind::Element{attrs,..}=&mut d.nodes[n].kind else{unreachable!()};attrs.iter_mut().find(|a|a.name.html_is(name)).unwrap().value=DomString::from_units(&[65,unit,122],4096).unwrap();}}let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),exact=document.getElementById('exact'),alias=document.getElementById('alias'),unrelated=document.getElementById('unrelated');output.value='detached current';document.getElementById('mount').appendChild(output);exact.value='exact current';alias.value='alias current';unrelated.value='other current';");p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),owner).unwrap();run(&mut d,&mut f,&mut p,"if(exact.value!=='exact default'||alias.value!=='alias current'||alias.defaultValue!=='alias default'||output.value!=='detached current'||output.defaultValue!=='beforetail'||unrelated.value!=='other current')throw 'actual exact reset association';exact.defaultValue='next';if(exact.value!=='next')throw 'exact reset cleared state';");}
#[test]
fn output_reset_form_outputs_publish_in_document_tree_order(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),second=document.createElement('output'),third=document.createElement('output'),order=[];second.id='second';third.id='third';document.getElementById('owner').appendChild(second);document.getElementById('owner').appendChild(third);output.value='current';second.value='current';third.value='current';var watch=new MutationObserver(function(records){for(var record of records)order.push(record.target.id);});watch.observe(document.body,{childList:true,subtree:true});");p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),owner).unwrap();run(&mut d,&mut f,&mut p,"if(order.length!==3||order[0]!=='output'||order[1]!=='second'||order[2]!=='third')throw 'OUTPUT reset tree order';");}
